<?php
require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../includes/session.php';require_once __DIR__.'/../includes/auth.php';
require_login();require_module_access($conn,'emergency','view');
$canCreate=can_module_action($conn,'emergency','create');$canEdit=can_module_action($conn,'emergency','edit');$csrf=csrf_token();$error='';$message='';
$triage=['Immediate','Very Urgent','Urgent','Standard','Non-Urgent'];$arrivals=['Walk-in','Ambulance','Police','Referral','Other'];$statuses=['Waiting','Under Assessment','Treatment','Admitted','Discharged','Transferred','Left Before Assessment','Cancelled'];
$validNumber=static function($v,$min,$max):bool{return $v===''|| (is_numeric($v)&&(float)$v>=$min&&(float)$v<=$max);};
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!verify_csrf_token($_POST['csrf_token']??null))$error='Your security token expired. Refresh the page and try again.';
 else{
  $action=(string)($_POST['action']??'create');
  if($action==='create'){
   if(!$canCreate){http_response_code(403);exit('Forbidden: emergency create permission required.');}
   $patientId=(int)($_POST['patient_id']??0);$arrival=(string)($_POST['arrival_mode']??'Walk-in');$complaint=trim((string)($_POST['chief_complaint']??''));$level=(string)($_POST['triage_level']??'Urgent');$notes=trim((string)($_POST['triage_notes']??''));$temp=trim((string)($_POST['temperature_c']??''));$sys=trim((string)($_POST['systolic_bp']??''));$dia=trim((string)($_POST['diastolic_bp']??''));$pulse=trim((string)($_POST['pulse_bpm']??''));$resp=trim((string)($_POST['respiratory_rate']??''));$spo2=trim((string)($_POST['oxygen_saturation']??''));$pain=trim((string)($_POST['pain_score']??''));$clinician=(int)($_POST['assigned_clinician_id']??0);
   if($patientId<1||$complaint===''||strlen($complaint)>1000||strlen($notes)>1500||!in_array($arrival,$arrivals,true)||!in_array($level,$triage,true))$error='Choose a patient, arrival mode and triage level, and enter the chief complaint.';
   elseif(!$validNumber($temp,25,45)||!$validNumber($sys,40,300)||!$validNumber($dia,20,200)||!$validNumber($pulse,1,300)||!$validNumber($resp,1,100)||!$validNumber($spo2,0,100)||!$validNumber($pain,0,10))$error='One or more vital signs are outside the permitted range.';
   else{
    $conn->begin_transaction();
    try{
     $p=$conn->prepare('SELECT id FROM patients WHERE id=? FOR UPDATE');if(!$p)throw new RuntimeException('patient prepare failed');$p->bind_param('i',$patientId);$p->execute();$patient=$p->get_result()->fetch_assoc();$p->close();if(!$patient)throw new InvalidArgumentException('Patient record was not found.');
     if($clinician>0){$u=$conn->prepare('SELECT id FROM users WHERE id=? LIMIT 1');if(!$u)throw new RuntimeException('clinician prepare failed');$u->bind_param('i',$clinician);$u->execute();$user=$u->get_result()->fetch_assoc();$u->close();if(!$user)throw new InvalidArgumentException('Selected clinician account was not found.');}
     $creator=(int)($_SESSION['user_id']??0);$visitNo='ER-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$visitType='Emergency';$clinic='Emergency/Casualty';$visitStatus='In Progress';$visit=$conn->prepare('INSERT INTO visits (visit_number,patient_id,visit_date,visit_time,visit_type,clinic_category,triage_priority,status,created_by) VALUES (?, ?, CURDATE(), CURTIME(), ?, ?, ?, ?, ?)');if(!$visit)throw new RuntimeException('visit prepare failed');$priority=$level==='Immediate'||$level==='Very Urgent'?'Emergency':($level==='Urgent'?'Urgent':'Routine');$visit->bind_param('sissssi',$visitNo,$patientId,$visitType,$clinic,$priority,$visitStatus,$creator);$visit->execute();$visitId=(int)$conn->insert_id;$visit->close();
     $tempV=$temp!==''?(float)$temp:null;$sysV=$sys!==''?(int)$sys:null;$diaV=$dia!==''?(int)$dia:null;$pulseV=$pulse!==''?(int)$pulse:null;$respV=$resp!==''?(int)$resp:null;$spo2V=$spo2!==''?(float)$spo2:null;$painV=$pain!==''?(int)$pain:null;$notesV=$notes!==''?$notes:null;$clinicianV=$clinician>0?$clinician:null;
     $sql='INSERT INTO emergency_cases (patient_id,visit_id,arrival_mode,chief_complaint,triage_level,triage_notes,temperature_c,systolic_bp,diastolic_bp,pulse_bpm,respiratory_rate,oxygen_saturation,pain_score,assigned_clinician_id,status,triaged_by,created_by,updated_by,triaged_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,\'Waiting\',?,?,?,NOW())';
     $st=$conn->prepare($sql);if(!$st)throw new RuntimeException('emergency case prepare failed');$st->bind_param('iissssdi iiiidi iii', $patientId,$visitId,$arrival,$complaint,$level,$notesV,$tempV,$sysV,$diaV,$pulseV,$respV,$spo2V,$painV,$clinicianV,$creator,$creator,$creator);$st->execute();$caseId=(int)$conn->insert_id;$st->close();
     if(function_exists('audit'))audit('emergency_case_created','case_id='.$caseId.',visit_id='.$visitId.',triage='.$level);$conn->commit();$message='Emergency case registered. Visit number: '.$visitNo.'.';
    }catch(Throwable $ex){$conn->rollback();if($ex instanceof InvalidArgumentException)$error=$ex->getMessage();else{error_log('Emergency intake failed: '.$ex->getMessage());$error='Emergency case could not be saved. Check that the visit and emergency migrations have been applied.';}}
   }
  }elseif($action==='update'){
   if(!$canEdit){http_response_code(403);exit('Forbidden: emergency edit permission required.');}
   $id=(int)($_POST['id']??0);$status=(string)($_POST['status']??'Waiting');$clinician=(int)($_POST['assigned_clinician_id']??0);$notes=trim((string)($_POST['disposition_notes']??''));
   if($id<1||!in_array($status,$statuses,true)||strlen($notes)>1500)$error='Choose a valid case status and keep disposition notes within 1,500 characters.';
   else{
    try{$conn->begin_transaction();$st=$conn->prepare('SELECT status FROM emergency_cases WHERE id=? FOR UPDATE');if(!$st)throw new RuntimeException('case lock prepare failed');$st->bind_param('i',$id);$st->execute();$existing=$st->get_result()->fetch_assoc();$st->close();if(!$existing)throw new InvalidArgumentException('Emergency case not found.');if(in_array($existing['status'],['Discharged','Transferred','Left Before Assessment','Cancelled'],true)&&$status!==$existing['status'])throw new InvalidArgumentException('A closed case cannot be reopened from this screen.');$clinicianV=$clinician>0?$clinician:null;$notesV=$notes!==''?$notes:null;$actor=(int)($_SESSION['user_id']??0);$closed=in_array($status,['Discharged','Transferred','Left Before Assessment','Cancelled'],true);$sql='UPDATE emergency_cases SET status=?,assigned_clinician_id=?,disposition_notes=?,updated_by=?,closed_at=IF(?=1,COALESCE(closed_at,NOW()),NULL) WHERE id=?';$up=$conn->prepare($sql);if(!$up)throw new RuntimeException('case update prepare failed');$closedInt=$closed?1:0;$up->bind_param('sisiii',$status,$clinicianV,$notesV,$actor,$closedInt,$id);$up->execute();$up->close();$visitStatus=$status==='Admitted'?'In Progress':(in_array($status,['Discharged','Transferred','Left Before Assessment','Cancelled'],true)?'Completed':'In Progress');$v=$conn->prepare('UPDATE visits v JOIN emergency_cases e ON e.visit_id=v.id SET v.status=? WHERE e.id=?');if(!$v)throw new RuntimeException('visit update prepare failed');$v->bind_param('si',$visitStatus,$id);$v->execute();$v->close();if(function_exists('audit'))audit('emergency_case_updated','case_id='.$id.',status='.$status);$conn->commit();$message='Emergency case updated.';
    }catch(Throwable $ex){$conn->rollback();if($ex instanceof InvalidArgumentException)$error=$ex->getMessage();else{error_log('Emergency update failed: '.$ex->getMessage());$error='Emergency case could not be updated.';}}
   }
  }
 }
}
$patients=$conn->query('SELECT id,patient_number,full_name,age,gender FROM patients ORDER BY full_name');
$users=$conn->query('SELECT id,full_name FROM users ORDER BY full_name');
$rows=$conn->query("SELECT e.*,p.patient_number,p.full_name,p.age,p.gender,v.visit_number,u.full_name clinician_name FROM emergency_cases e JOIN patients p ON p.id=e.patient_id JOIN visits v ON v.id=e.visit_id LEFT JOIN users u ON u.id=e.assigned_clinician_id ORDER BY FIELD(e.status,'Waiting','Under Assessment','Treatment','Admitted','Discharged','Transferred','Left Before Assessment','Cancelled'),FIELD(e.triage_level,'Immediate','Very Urgent','Urgent','Standard','Non-Urgent'),e.arrived_at");
$summary=$conn->query("SELECT COUNT(*) total,SUM(status IN ('Waiting','Under Assessment','Treatment')) open_count,SUM(triage_level IN ('Immediate','Very Urgent') AND status IN ('Waiting','Under Assessment','Treatment')) critical_count FROM emergency_cases");$counts=$summary?$summary->fetch_assoc():['total'=>0,'open_count'=>0,'critical_count'=>0];
$e=static fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');include __DIR__.'/../includes/header.php';include __DIR__.'/../includes/sidebar.php';
