<section class="er-card"><div class="er-head">Casualty queue · highest acuity first</div><div class="er-tablewrap"><table class="er-table"><thead><tr><th>Patient / visit</th><th>Arrival</th><th>Presenting problem / triage notes</th><th>Triage</th><th>Observations</th><th>Assigned clinician</th><th>Status / disposition</th></tr></thead><tbody><?php if($rows&&$rows->num_rows):while($r=$rows->fetch_assoc()):$priorityClass=in_array($r['triage_level'],['Immediate','Very Urgent'],true)?'er-immediate':($r['triage_level']==='Urgent'?'er-urgent':'');$closed=in_array($r['status'],['Discharged','Transferred','Left Before Assessment','Cancelled'],true);?><tr><td><span class="er-name"><?= $e($r['full_name']) ?></span><span class="er-sub"><?= $e($r['patient_number']) ?> · <?= $e($r['visit_number']) ?></span><span class="er-sub"><?= $e($r['age']) ?> yrs · <?= $e($r['gender']) ?></span></td><td><?= $e($r['arrived_at']) ?><span class="er-sub"><?= $e($r['arrival_mode']) ?></span></td><td><?= $e($r['chief_complaint']) ?><span class="er-sub"><?= $e($r['triage_notes']?:'No triage notes') ?></span></td><td><span class="er-pill <?= $priorityClass ?>"><?= $e($r['triage_level']) ?></span></td><td><?= $e($r['temperature_c']!==null?$r['temperature_c'].' °C':'—') ?><span class="er-sub">BP <?= $e($r['systolic_bp']!==null?$r['systolic_bp'].'/'.$r['diastolic_bp']:'—') ?> · Pulse <?= $e($r['pulse_bpm']??'—') ?></span><span class="er-sub">RR <?= $e($r['respiratory_rate']??'—') ?> · SpO₂ <?= $e($r['oxygen_saturation']??'—') ?> · Pain <?= $e($r['pain_score']??'—') ?></span></td><td><?= $e($r['clinician_name']?:'Unassigned') ?></td><td><?php if($canEdit&&!$closed):?><form method="post" class="er-inline"><input type="hidden" name="csrf_token" value="<?= $e($csrf) ?>"><input type="hidden" name="action" value="update"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><select name="status"><?php foreach($statuses as $st):?><option value="<?= $e($st) ?>" <?= $r['status']===$st?'selected':'' ?>><?= $e($st) ?></option><?php endforeach;?></select><select name="assigned_clinician_id"><option value="0">Unassigned</option><?php if($users):while($u=$users->fetch_assoc()):?><option value="<?= (int)$u['id'] ?>" <?= ((int)($r['assigned_clinician_id']??0)===(int)$u['id'])?'selected':'' ?>><?= $e($u['full_name']) ?></option><?php endwhile;$users->data_seek(0);endif;?></select><textarea name="disposition_notes" rows="2" maxlength="1500" placeholder="Disposition / handover notes"><?= $e($r['disposition_notes']??'') ?></textarea><button class="er-btn er-primary" type="submit">Update</button></form><?php else:?><span class="er-pill <?= $closed?'er-closed':'er-open' ?>"><?= $e($r['status']) ?></span><span class="er-sub"><?= $e($r['disposition_notes']?:'') ?></span><?php endif;?></td></tr><?php endwhile;else:?><tr><td colspan="7" style="text-align:center;padding:35px;color:#77869a">No emergency cases recorded yet.</td></tr><?php endif;?></tbody></table></div></section></div></div>
